CREATE OR REPLACE FUNCTION public.get_viewing_room_choices(_token text,_package_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$
DECLARE data jsonb; p public.furniture_packages; items jsonb;
BEGIN
 data:=public.get_viewing_room_package(_token,_package_id); IF data IS NULL THEN RETURN NULL; END IF;
 SELECT * INTO p FROM public.furniture_packages WHERE id=_package_id;
 SELECT jsonb_agg(j || jsonb_build_object('retail_price',CASE WHEN p.currency='EUR' THEN (public._shared_board_retail_price(t.rrp_price_cents,t.size_variants,i.variant_label)->>'cents')::numeric/100 ELSE NULL END,'retail_price_from',coalesce((public._shared_board_retail_price(t.rrp_price_cents,t.size_variants,i.variant_label)->>'from')::boolean,false),'allow_finish_customization',coalesce(r.allow_finish_customization,true),'is_swappable',p.allow_alternatives AND coalesce(r.is_swappable,true),'alternatives',CASE WHEN NOT p.allow_alternatives OR r.is_swappable=false THEN '[]'::jsonb WHEN r.id IS NOT NULL THEN coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'product_name',c.name,'category',c.category_role,'subcategory',NULL,'image_url',alt.image_url,'dimensions',concat(c.width_m,' × ',c.depth_m,' × ',c.height_m,' m'),'width_mm',c.width_m*1000,'depth_mm',c.depth_m*1000,'height_mm',c.height_m*1000,'glb_url',coalesce(c.glb_url_compressed,c.glb_url_proxy),'lead_time',CASE WHEN c.base_lead_time_weeks IS NOT NULL THEN c.base_lead_time_weeks::text||' weeks' END,'materials','{}'::jsonb,'retail_price',c.base_price_sgd * CASE WHEN p.currency='SGD' THEN 1 ELSE (SELECT rate FROM currency_rates WHERE base_currency='SGD' AND target_currency=p.currency ORDER BY rate_date DESC LIMIT 1) END,'retail_price_from',false) ORDER BY c.name) FROM catalog_items c JOIN catalog_items original ON original.id=i.product_id LEFT JOIN trade_products alt ON alt.id=c.id WHERE c.id=ANY(r.pinned_alternative_ids) AND c.id<>original.id AND c.category_role=original.category_role AND original.width_m>0 AND original.depth_m>0 AND c.width_m BETWEEN original.width_m*.85 AND original.width_m*1.15 AND c.depth_m BETWEEN original.depth_m*.85 AND original.depth_m*1.15 AND coalesce(c.glb_url_compressed,c.glb_url_proxy) ~* '^https?://' AND (alt.id IS NULL OR (alt.is_active AND NOT coalesce(alt.is_hidden,false)))),'[]'::jsonb) ELSE coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.product_id,'product_name',alt.product_name,'category',alt.category,'subcategory',alt.subcategory,'image_url',alt.image_url,'dimensions',alt.dimensions,'width_mm',alt.width_mm,'depth_mm',alt.depth_mm,'height_mm',alt.height_mm,'glb_url',coalesce((SELECT c.glb_url_compressed FROM catalog_items c WHERE c.id=alt.id),alt.glb_url),'lead_time',alt.lead_time,'materials','{}'::jsonb,'retail_price',a.retail_price,'retail_price_from',a.retail_price_from) ORDER BY a.sort_order,alt.product_name) FROM viewing_room_slot_alternatives a JOIN trade_products alt ON alt.id=a.product_id WHERE a.package_id=p.id AND a.slot_id=i.id AND alt.is_active AND NOT coalesce(alt.is_hidden,false) AND coalesce((SELECT c.glb_url_compressed FROM catalog_items c WHERE c.id=alt.id),alt.glb_url) ~* '^https?://[^[:space:]]+\.(glb|gltf|obj)([?#].*)?$'),'[]'::jsonb) END)) INTO items FROM jsonb_array_elements(data->'items') j JOIN client_board_items i ON i.id=(j->>'id')::uuid JOIN trade_products t ON t.id=i.product_id LEFT JOIN hotspot_slot_rules r ON r.furniture_package_id=p.id AND r.board_item_id=i.id;
 RETURN jsonb_build_object('items',coalesce(items,'[]'::jsonb),'allow_alternatives',p.allow_alternatives);
END $$;